pub fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    debug_assert!(len > 0, "input list must be non-empty");

    let shift = n % len;
    let s = len - shift; // as specified: s = len - (n mod len)

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..len]); // suffix [s, len)
    new_list.extend_from_slice(&list[0..s]);   // prefix [0, s)
    new_list
}